import { chromium } from '@playwright/test'
const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })
const p = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
await p.route(/font|woff2?|\.ttf|\.otf/i, r=>r.abort()).catch(()=>{})
const reqs = []
p.on('request', r => { if (r.url().includes('/v2.0/code')) reqs.push(r.url()) })
await p.goto('http://127.0.0.1:8095/#/pages/login-design/index', { waitUntil: 'domcontentloaded' })
await p.waitForTimeout(3500)
const imgCount = await p.locator('.login-captcha-image').count()
const phCount = await p.locator('.login-captcha-ph').count()
console.log('design-login captcha requests:', JSON.stringify(reqs))
console.log('image count:', imgCount, 'placeholder count:', phCount)
await browser.close()

import { chromium } from '@playwright/test'
const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })
const p = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
await p.route(/font|woff2?|\.ttf|\.otf/i, r=>r.abort()).catch(()=>{})
const net = []
p.on('request', r => { const u=r.url(); if (u.includes('/api/')) net.push(r.method()+' '+u.replace('http://127.0.0.1:8095','')) })
await p.goto('http://127.0.0.1:8095/', { waitUntil: 'domcontentloaded' })
await p.waitForTimeout(3000)
// captcha shown?
const imgCnt = await p.locator('.login-captcha-image').count()
console.log('captcha image count:', imgCnt)
// fill username/password (plain pwd; store encrypts via aes)
const inputs = p.locator('input')
const n = await inputs.count()
console.log('input count:', n)
// input[0]=username, input[1]=password, input[2]=captcha
await inputs.nth(0).fill('zsbase')
await inputs.nth(1).fill('Zs@2026Aa!')
// fill captcha with something (backend captcha may reject wrong; we mainly check no '真实接口未配置')
if (await inputs.count() >= 3) await inputs.nth(2).fill('1234').catch(()=>{})
await p.locator('input[type=checkbox]').check().catch(()=>{})
await p.locator('.login-submit').click()
await p.waitForTimeout(3000)
const errVisible = await p.locator('.login-error').count()
let errText = ''
if (errVisible) errText = (await p.locator('.login-error').first().innerText()) || ''
console.log('login-error count:', errVisible, 'text:', errText)
console.log('url after login:', p.url())
console.log('network /api calls:', JSON.stringify(net, null, 0))
await p.screenshot({ path:'artifacts/login-remote-test.png', animations:'disabled', timeout:30000 }).catch(()=>{})
await browser.close()

