import { chromium } from '@playwright/test'
const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })
const p = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
await p.route(/font|woff2?|\.ttf|\.otf/i, r=>r.abort()).catch(()=>{})
// login
await p.goto('http://127.0.0.1:8095/', { waitUntil: 'domcontentloaded' }); await p.waitForTimeout(2500)
const inputs = p.locator('input')
await inputs.nth(0).fill('zsbase')
await inputs.nth(1).fill('Zs@2026Aa!')
await inputs.nth(2).fill('1234').catch(()=>{})
await p.locator('.login-agreement').click()
await p.locator('.login-submit').click()
await p.waitForTimeout(3500)
console.log('after login url:', p.url())
// go inspection mid
await p.goto('http://127.0.0.1:8095/#/pages/inspection/index?kind=mid', { waitUntil: 'domcontentloaded' })
await p.waitForTimeout(2500)
const alertCount = await p.locator('[role="alert"]').count()
const formAlertCount = await p.locator('.form-alert').count()
console.log('role=alert count:', alertCount, '| .form-alert count:', formAlertCount)
// try submit without complex -> expect toast
const submitBtn = p.getByText('提交', { exact: true }).first()
if (await submitBtn.count()) { await submitBtn.click(); await p.waitForTimeout(800) }
const toastVisible = await p.locator('uni-toast, .uni-toast').count()
const bodyText = await p.evaluate(()=>document.body.innerText)
console.log('toast element count:', toastVisible, '| body has 请选择物业管理区域:', bodyText.includes('请选择物业管理区域'))
await p.screenshot({ path:'artifacts/lead-error-toast-verify.png', animations:'disabled', timeout:30000 }).catch(()=>{})
await browser.close()

